/// ASN.1 `GeographyBasedMDT` (NGAP-IEs).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct GeographyBasedMdt {
    /// `nTN-Geographical-Area`
    pub ntn_geographical_area: NtnGeographicalAreaList,
    /// `nTN-PLMN-List`
    pub ntn_plmn_list: Option<MdtplmnList>,
    /// `iE-Extensions`
    pub ie_extensions: Option<rt::ie::UnknownIes>,
}

impl GeographyBasedMdt {
    /// A value with the mandatory components given and every optional one absent.
    pub fn new(ntn_geographical_area: NtnGeographicalAreaList) -> Self {
        Self {
            ntn_geographical_area,
            ntn_plmn_list: None,
            ie_extensions: None,
        }
    }
}

impl rt::AperEncode for GeographyBasedMdt {
    fn aper_encode(&self, w: &mut rt::BitWriter) -> rt::Result<()> {
        w.write_bit(false); // extension marker: no additions
        w.write_bit(self.ntn_plmn_list.is_some());
        w.write_bit(self.ie_extensions.is_some());
        {
            let x = &self.ntn_geographical_area;
            x.aper_encode(w)?;
        }
        if let Some(x) = &self.ntn_plmn_list {
            x.aper_encode(w)?;
        }
        if let Some(x) = &self.ie_extensions {
            rt::ie::write_container(w, rt::Size::range(1, 65535), &x.ies)?;
        }
        Ok(())
    }
}

impl rt::AperDecode for GeographyBasedMdt {
    fn aper_decode(r: &mut rt::BitReader<'_>) -> rt::Result<Self> {
        let extension = r.read_bit()?;
        let p_ntn_plmn_list = r.read_bit()?;
        let p_ie_extensions = r.read_bit()?;
        let v_ntn_geographical_area = <NtnGeographicalAreaList>::aper_decode(r)?;
        let v_ntn_plmn_list = if p_ntn_plmn_list { Some(<MdtplmnList>::aper_decode(r)?) } else { None };
        let v_ie_extensions = if p_ie_extensions { Some(rt::ie::read_container(r, rt::Size::range(1, 65535)).map(|ies| { ies.iter().for_each(rt::ie::note_unknown); rt::ie::UnknownIes { ies } })?) } else { None };
        if extension {
            r.read_extension_additions()?;
        }
        Ok(Self {
            ntn_geographical_area: v_ntn_geographical_area,
            ntn_plmn_list: v_ntn_plmn_list,
            ie_extensions: v_ie_extensions,
        })
    }
}

/// ASN.1 `GlobalCable-ID` (NGAP-IEs).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct GlobalCableId(pub Vec<u8>);

impl rt::AperEncode for GlobalCableId {
    fn aper_encode(&self, w: &mut rt::BitWriter) -> rt::Result<()> {
        let x = &self.0;
        w.write_octet_string(x, rt::Size::UNBOUNDED)
    }
}

impl rt::AperDecode for GlobalCableId {
    fn aper_decode(r: &mut rt::BitReader<'_>) -> rt::Result<Self> {
        Ok(Self(r.read_octet_string(rt::Size::UNBOUNDED)?))
    }
}
